    public static let roomC: ClosedRange<Double> = 5.0...40.0
    public static let altitudeM: ClosedRange<Double> = -400.0...5000.0
    public static let waterLitres: ClosedRange<Double> = 0.25...12.0
    /// A bowl of water to cool the eggs in: half a litre covers two eggs in a cereal bowl; eight is
