    public static let coolingWaterC: ClosedRange<Double> = 1.0...40.0
    public static let eggCount: ClosedRange<Double> = 1.0...24.0
    public static let doneness: ClosedRange<Double> = 0.0...1.0
    /// Across every table.
    public static let sizeIndex: ClosedRange<Double> = -1.0...4.0
    /// A tap under half a minute is a double tap, not a boil; over two hours is an app left open.
